package ai.fitnova.service;
import ai.fitnova.api.ApiDtos.*; import ai.fitnova.domain.*; import ai.fitnova.repo.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class WorkoutService {private final WorkoutRepository workouts;private final ReadinessRepository readiness;private final ProfileRepository profiles;
 @Transactional public WorkoutView generate(User u,WorkoutRequest r){Profile p=profiles.findByUserId(u.getId()).orElseThrow();ReadinessEntry latest=readiness.findFirstByUserIdOrderByEntryDateDescIdDesc(u.getId()).orElse(null);int minutes=Math.max(10,r.minutes());String condition=latest==null?"":Optional.ofNullable(latest.getCurrentCondition()).orElse("").toLowerCase();boolean unsafe=List.of("significant pain","dizziness","fever","breathing difficulty","recent significant injury").stream().anyMatch(condition::contains);String intensity=unsafe||latest!=null&&latest.getScore()<35?"RECOVERY":latest!=null&&latest.getScore()<65?"LIGHT":"MODERATE";List<String> exercises=buildExercises(intensity,r.focus(),r.equipment(),p.getLimitations(),minutes);Workout w=new Workout();w.setUser(u);w.setTitle(intensity.equals("RECOVERY")?"RECOVERY SESSION":r.focus().toUpperCase());w.setDurationMinutes(minutes);w.setIntensity(intensity);w.setLocation(r.location());w.setGoal(r.focus());w.setExercises(String.join("|",exercises));w.setStatus("PLANNED");return view(workouts.save(w));}
 @Transactional(readOnly=true) public List<WorkoutView> history(User u){return workouts.findTop30ByUserIdOrderByIdDesc(u.getId()).stream().map(this::view).toList();}
 @Transactional public WorkoutView start(User u,Long id){Workout w=owned(u,id);if(w.getStartedAt()==null)w.setStartedAt(Instant.now());w.setStatus("IN_PROGRESS");return view(workouts.save(w));}
 @Transactional public WorkoutView complete(User u,Long id,WorkoutFeedback f){Workout w=owned(u,id);w.setStatus("COMPLETED");w.setCompletedAt(Instant.now());if(w.getStartedAt()==null)w.setStartedAt(w.getCompletedAt().minusSeconds(w.getDurationMinutes()*60L));if(f!=null){w.setFeedback(f.feedback());w.setEnergyAfter(f.energyAfter());w.setNotes(f.notes());}return view(workouts.save(w));}
 public WorkoutView view(Workout w){return new WorkoutView(w.getId(),w.getTitle(),w.getDurationMinutes(),w.getIntensity(),w.getLocation(),w.getStatus(),split(w.getExercises()),w.getFeedback(),w.getStartedAt(),w.getCompletedAt());}
 private Workout owned(User u,Long id){return workouts.findById(id).filter(w->w.getUser().getId().equals(u.getId())).orElseThrow(()->new NoSuchElementException("Workout not found"));}
 private List<String> buildExercises(String intensity,String focus,List<String> equipment,String limitations,int minutes){if("RECOVERY".equals(intensity))return List.of("Breathing reset · 2 min","Gentle mobility · "+Math.max(5,minutes-7)+" min","Easy walk · 3 min","Cooldown · 2 min");List<String> pool=new ArrayList<>(List.of("Bodyweight squat · 3 sets","Incline push-up · 3 sets","Reverse lunge · 3 sets","Glute bridge · 3 sets","Dead bug · 3 sets"));String eq=String.join(" ",equipment==null?List.of():equipment).toLowerCase();if(eq.contains("dumbbell")){pool.set(0,"Dumbbell squat · 3 sets");pool.add("Single-arm row · 3 sets");pool.add("Shoulder press · 3 sets");}String limits=Optional.ofNullable(limitations).orElse("").toLowerCase();if(limits.contains("knee"))pool.removeIf(x->x.toLowerCase().contains("squat")||x.toLowerCase().contains("lunge"));int mainSlots=Math.max(2,Math.min(pool.size(),(minutes-6)/5));List<String> result=new ArrayList<>();result.add("Dynamic warm-up · 3 min");result.addAll(pool.subList(0,mainSlots));result.add("Cooldown · 3 min");return result;}
 private List<String> split(String value){return value==null||value.isBlank()?List.of():Arrays.asList(value.split("\\|"));}}
